// random walker
////////////////

class Walker {
  constructor(x, y, step) {
    this.x = x;
    this.y = y;
    this.step = step;
    this.size = this.step / random([1, 2, 5, 10]);
    this.color1 = generateColor(100);
    this.color2 = generateColor(100);
    this.rad = this.step / 2;
    this.w = random([1, 10, 100]);
    this.shape = random(["line", "point"]);
  }

  draw(pg) {
    const oldX = this.x;
    const oldY = this.y;

    // paso aleatorio en grilla
    this.x += this.step * random([-1, 1]);
    this.y += this.step * random([-1, 1]);

    pg.strokeWeight(this.w);
    pg.stroke(this.color2);

    this.w *= 0.95;
    this.rad *= 0.95;

    if (this.shape === "line") {
      pg.line(oldX, oldY, this.x, this.y);

      if (this.w > 10) {
        pg.strokeWeight(this.w / 2);
        pg.stroke(this.color1);
        pg.line(oldX, oldY, this.x, this.y);
      }
    } else {
      pg.noStroke();
      pg.fill(this.color2);
      pg.circle(this.x, this.y, this.rad);
      pg.fill(this.color1);
      pg.circle(this.x, this.y, this.rad / 2);
    }
  }
}

function generateColor(myAlpha = 100) {
  const myColor = color(random(colors));
  myColor.setAlpha(myAlpha);
  return myColor;
}

function drawGrid() {
  stroke(0);
  strokeWeight(10);

  for (let x = 20; x < height; x += 320) {
    line(0, x, width, x);
    line(x, 0, x, height);
  }

  for (let x = 20; x < height; x += 320) {
    line(20, x, width - 20, x);
    line(x, 20, x, height - 20);
  }

  noFill();
}

function addNoiseOverlay(strength = 50) {
  push();
  blendMode(OVERLAY);
  stroke(255, 50);
  for (let i = 0; i < strength * 1000; i++) {
    point(random(width), random(height));
  }
  pop();
}

function buildCanvasTexture(w, h, opt = {}) {
  const {
    cell = 3,
    jitter = 0.25,
    alpha = 20,
    grain = 10,
    vignet = 0.12
  } = opt;

  const tex = createGraphics(w, h);
  tex.pixelDensity(1);
  tex.loadPixels();

  const freqX = 1 / (cell * 1.0);
  const freqY = 1 / (cell * 1.0);

  function vignetteFactor(x, y) {
    const nx = (x / (w - 1)) * 2 - 1;
    const ny = (y / (h - 1)) * 2 - 1;
    const r2 = nx * nx + ny * ny;
    const v = 1 - vignet * r2;
    return constrain(v, 0.7, 1);
  }

  for (let y = 0; y < h; y++) {
    const rowWeft = 0.5 + 0.5 * Math.sin(y * freqY * TWO_PI + 0.7);
    for (let x = 0; x < w; x++) {
      const colWarp = 0.5 + 0.5 * Math.sin(x * freqX * TWO_PI + 1.1);
      let intensity = rowWeft * colWarp;

      intensity += (random() - 0.5) * 2 * jitter;

      if (grain > 0) {
        intensity += (random() - 0.5) * (grain / 255.0);
      }

      intensity = constrain(pow(constrain(intensity, 0, 1), 0.9), 0, 1);
      intensity *= vignetteFactor(x, y);

      const g = floor(255 * intensity);
      const a = alpha;

      const idx = 4 * (y * w + x);
      tex.pixels[idx + 0] = g;
      tex.pixels[idx + 1] = g;
      tex.pixels[idx + 2] = g;
      tex.pixels[idx + 3] = a;
    }
  }

  tex.updatePixels();

  tex.push();
  tex.stroke(255, 12);
  tex.strokeWeight(1);
  for (let yy = 0; yy < h; yy += cell * 8) tex.line(0, yy, w, yy);
  for (let xx = 0; xx < w; xx += cell * 8) tex.line(xx, 0, xx, h);
  tex.pop();

  return tex;
}

function darker(c, factor) {
  return color(hue(c), saturation(c), brightness(c) * factor);
}


